window.addEventListener('load',()=>{setTimeout(()=>{const dict=globalThis.COOP_KO||{};let queued=false;function translate(){queued=false;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode(n){return ['SCRIPT','STYLE','TEXTAREA','CODE','NOSCRIPT'].includes(n.parentElement?.tagName)?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}});const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const n of nodes){const t=n.nodeValue.trim();if(dict[t]&&dict[t]!==t)n.nodeValue=n.nodeValue.replace(t,dict[t])}for(const el of document.querySelectorAll('[placeholder],[title],[aria-label]'))for(const attr of ['placeholder','title','aria-label']){const t=el.getAttribute(attr);if(dict[t])el.setAttribute(attr,dict[t])}document.documentElement.lang='ko'}new MutationObserver(()=>{if(!queued){queued=true;requestAnimationFrame(translate)}}).observe(document.body,{subtree:true,childList:true,characterData:true});translate();document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(a&&a.origin===location.origin&&!a.hash&&!a.download&&!e.ctrlKey&&!e.metaKey){e.preventDefault();e.stopImmediatePropagation();location.assign(a.href)}},true);const nav=document.createElement('div');nav.style.cssText='padding:10px 18px;background:#244535;color:#d5e9c4;font:12px/1.8 system-ui;position:relative;z-index:10000';nav.innerHTML='<a href="/" style="color:inherit">← 한국어 전투력 연구소</a><span style="margin-left:20px;opacity:.7">원본 계산 도구 · 주요 용어 한국어 적용 / 일부 설명 원문</span>';document.body.prepend(nav);},1000)},{once:true});